def min_tshirts(N: int, C: int, sizes: List[int]) -> int:
    left = 0
    right = N * (N//2) - 500  # Reducing T-shirt sizes to make the numbers more manageable
    mid = (left + right) // 2  
    while left < right:
        if (left + right + 1) // 2 > C:
            left = mid
        else:
            right = mid
        mid = (left + right + 1) // 2  # Finding a lower upper bound
    total_tshirts = 0
    for i in range(N):
        cand1_tshirts = N // 2 - i
        cand2_tshirts = N - i
        if sizes[i] > left and sizes[2*i+1] > right:
            total_tshirts += min(cand1_tshirts, cand2_tshirts)
        elif sizes[i] > left and sizes[2*i+1] <= right:
            total_tshirts += min(cand1_tshirts, cand2_tshirts, (left - sizes[2*i+1]))
        elif sizes[i] <= left and sizes[2*i+1] > right:
            total_tshirts += min(cand1_tshirts, cand2_tshirts)
    return total_tshirts
