from collections import deque, defaultdict

def dijkstra(graph, src, dst):
    n = len(graph)
    dist = [float('inf')] * n
    visited = [False] * n
    pq = [(0, src)]
    dist[src] = 0

    while pq:
        cost, v = pq.pop()
        if visited[v] or cost > dist[v]:
            continue
        visited[v] = True
        for w in graph[v]:
            if dist[w] > dist[v] + 1:
                dist[w] = dist[v] + 1
                pq.append((dist[w], w))

    return dist[dst] if dist[dst] != float('inf') else -1

