from collections import defaultdict

def simplify_broom(n, edges, letters):
    graph = defaultdict(list)
    for u, v, letter in edges:
        graph[u].append((v, letter))
        graph[v].append((u, letter))

    visited = [0] * (n + 2)
    result = []
    shortest_p = None

    def bfs(start):
        queue = [(start, 0)]
        visited[start] = 1
        current_p = 0
        while queue:
            vertex, p = queue.pop(0)
            if current_p < p:
                current_p = p
                shortest_p = vertex
            for neighbor, letter in graph[vertex]:
                if visited[neighbor] == 0:
                    visited[neighbor] = 1
                    queue.append((neighbor, p + 1))
        return current_p

    for start in range(2, n + 1):
        if visited[start] == 0:
            p = bfs(start)
            if shortest_p is None or p < shortest_p:
                shortest_p = p

    for start in range(2, n + 1):
        if visited[start] == 0:
            p = bfs(start)
            total_depth = sum(graph[v][0][0] for v in graph[start])
            if total_depth + p <= n:
                result.append(build_broom(start, total_depth, p))
            else:
                result.append(build_broom(start, total_depth + 1, 0))

    return min(result), shortest_p

def build_broom(start, depth, leaves):
    broom = [[None] * depth for _ in range(n)]
    current_depth = 0
    broom[1][0] = [start]
    while current_depth < depth:
        parent = broom[start][current_depth]
        for child in graph[start]:
            if parent:
                leaf = broom[child[0]][current_depth]
                if parent[0] < child[0] or (parent == 0 and child[0] < len(parent)):
                    leave = list(child[1:])
                    for j in range(len(parent)):
                        if j < len(leave):
                            parent[-1].append(leave[j])
                        else:
                            parent.j.append(0)
                    break
                if child[0] not in leave:
                    leave.append(child[0])
            else:
                broom[child[0]][current_depth] = leave = []
                start = child[1]
        current_depth += 1
    return broom

