import sys

def flip(s):
    count = 0
    for i in range(len(s)):
        if s[i] == '1':
            count += 1
    return count

def compress(s):
    compressed = ''
    count = 0
    for i in range(len(s)):
        if count == 0 or s[i] != s[i-1]:
            compression = int(s[i])
            if s[i] == '0':
                compression |= 2
            if compression == 2:
                compressed += '|'
            else:
                compressed += chr(compression)
        count = 0
        count += int(s[i])
    return compressed

def min_operations(S):
    operations = 0
    for i in range(len(S)):
        # Check if all characters are already the same before flipping
        if all(c == S[0] for c in S):
            return operations  # Done without any operation

        # Check if all characters are 1 and make them 0 with a flip
        elif all(c == '1' for c in S):
            operations += flip(S)
            continue

        # Count the number of zeros in the string
        count_zeros = S.count('0')
        operations += count_zeros

        # Group consecutive zeros and compress them
        compressed = compress(S)
        new_s = list(compressed)

        # Decode the compressed string back into a binary string
        binary_str = new_s.decode('ascii')

        # Add zero counts at the beginning of the binary string
        zero_counts = count_zeros
        while zero_counts > 0:
            while '0' in binary_str:
                index = binary_str.index('1')
                if index == 0:
                    if all(c == '0' for c in binary_str):
                        return operations - flip(binary_str) + 1  # Done without any operation
                    else:
                        return operations  # Operation is required for Compression
                binary_str = binary_str[index:1] + '0' + binary_str[:index+1]
                break
            zero_counts -= 1

        S = binary_str

    return operations

T = int(input())
for _ in range(T):
    S = input()
    print(min_operations(S))
