        new_order[indices[i]] = i + 1

    # Verify if the new order matches the given final order
    for i in range(len(new_order) - 1):
        if new_order[i] == i + 1 and new_order[i+1] != i + 1:
            return i

    return len(new_order) # If no horses changed places, there must be at least 3 commands (L, M, R positions)

