def smallest_permutation(N, p):
    q = []
    while p:
        i = 0
        while i < len(p) - 1 and p[i] <= p[i + 1]:
            i += 1
        if i == len(p) - 2:
            for x in reversed(p):
                q.append(x)
        else:
            new_p = []
            while i < len(p) - 1:
                new_p.append(min(p[i], p[i + 1]))
                i += 2
            for x in new_p:
                q.append(x)
        p = new_p
    return q

