    for i in range(1, 1 << n):
        turns = 0
        red_tokens = blue_tokens = 0
        cards_to_buy = dict()
        cards_needed = {i for i in range(1, 1 << n)}

        for j in range(n):
            card = format(cards[j][1:], 'b')
            for k in range(len(card)):
                card = card.replace('1', '', 1)
                if card[0] == '1':
                    red_tokens += 1
                    card_to_buy = tuple(map(int, reversed(card)))
                    if card_to_buy in cards_to_buy:
                        cards_to_buy[card_to_buy] += 1
                    else:
                        cards_to_buy[card_to_buy] = 1
                elif card[0] == '0':
                    blue_tokens += 1

            if len(cards_needed) == 0:
                break
            for k in range(1, 1 << n):
                if k in cards_needed and k != i:
                    cards_needed.discard(k)
                    red = blue = 0
                    for j in range(n):
                        card = format(k ^ i, 'b')
                        if card[0] == '1':
                            red += 1
                            card_to_buy = tuple(map(int, reversed(card)))
                            cards_to_buy[card_to_buy] += 1
                        elif card[0] == '0':
                            blue += 1

                    if red < blue:
                        cards_needed = set(map(int, format(i ^ k, 'b')))

            if i & n ^ 1 == i:
                break
        if len(cards_needed) == 0:
            min_turns = min(min_turns, turns)
    return min_turns + n

