    longest_segment = None
    current_segment_end = starting_index
    for current_segment_start in range(starting_index - 1, -1, -1):
        current_segment_end = max(current_segment_end, order_diffs[current_segment_start])
        if current_segment_end - current_segment_start + 1 > len(longest_segment) if longest_segment is not None else True:
            longest_segment = pair(current_segment_start, current_segment_end)

    shortest_gap = None
    current_gap_start = starting_index
    for current_gap_end in range(starting_index + 1, len(order_diffs) + 1):
        if order_diffs[current_gap_start] - order_diffs[current_gap_end] != order_diffs[current_gap_start]:
            current_gap_start = current_gap_end + 1
            current_gap_end = current_gap_start
            shortest_gap = (current_gap_start, current_gap_end)
            # At least two segments can be the result
            if len(longest_segment) > len(shortest_gap) and longest_segment[0] != shortest_gap[0]:
                longest_segment = shortest_gap

    if longest_segment is not None:
        # Swap between two segments in an even number,
        # or all swap if current gap is within two gaps
        if len(longest_segment) % 2 == 0 or shortest_gap[0] == starting_index or shortest_gap[1] == starting_index + len(order_diffs) - 1:
            # Larger segment higher by even number of slots
            if longest_segment[1] - longest_segment[0] - 1 >= 2:
                return [longest_segment] + find_commands(final_order, initial_order, longest_segment[0] + 1)
    return []

