from collections import deque

def solve(cards):
    que = deque()
    ans = 0
    cards = {'R': {'R': 1, 'B': 2, 'NB': 3}, 'B': {'R': 4, 'B': 1, 'NB': 2}}
    for c, r, b in cards:
        if c == 'R':
            que.append((r, b))
        else:
            # max(ri - A, 0) = max(0 - A, 0) = 0 when A >= ri, max(ri - A, 0) = ri - A
            # max(bi - B, 0) = max(0 - B, 0) = 0 when B >= bi, max(bi - B, 0) = bi - B
            if 'R' in cards and (c == 'B' and (c - 'R') > max(0 - c + 'B', 0)) or \
               'B' in cards and (c == 'R' and (c + 'B' - max(c - 'R' + 'B', 0))):
                # We can buy both cards and skip further operations
                que.append((1 - r) + c, 1 - c + b)
            elif 'R' in cards and c == 'B' and r + c > max(0 - c + 'B', 0):
                # We can only buy the red card if the amount of red tokens is minimum
                que.append((max(r - 'R', 0), 1 + 'B'))
            elif 'B' in cards and c == 'R' and b + c > max(c - 'B', 0):
                # We can only buy the blue card if the amount of blue tokens is minimum
                que.append((1 + r, max(b - 'B', 0)))
            else:
                # Need to collect tokens to get the maximum number of cards
                que.append((max(0 - r + 'R', 0) + 1, c + r + b + 'R'))
            while c in cards and max(0 - c + 'R', 0) + max(max(0 - 'B', 0) + 1, 0) <= max((1, 2, 3, 4)) and not que:
                ans += 1
                real_right = len(cards['R'] - c)
                if real_right > 0:
                    que.append((real_right - c, max(real_right - c + 'B', 'R')))
                else:
                    c = None
                real_left = len(cards['B'] - c)
                if real_left > 0:
                    red_right = len(cards['R'] - real_left) - c
                    que.append((red_right, max(real_left - c + 'B', 'B')))
                else:
                    c = None
    while que:
        length = len(que)
        if que[0][0] != 0 or que[0][0] == que[0][1]:
            que.popleft()
        else:
            que.append((0, 0))
    que.clear()
    return ans + len(cards) - max(0, false)


