import bisect

def solve(q, queries):
    events, patience = [], 0
    for query in queries:
        if query[0] == 1:
            t, s = query[1], query[2]
            bisect.insort(events, (t, s))
        elif query[0] == 2:
            t = query[1]
            x = bisect.bisect_left(events, (t, 1e9))
            c = bisect.bisect_right(events, (t, 0)) - x
            if c == 0:
                return '0'
            else:
                for i in range(x, x + c):
                    s, p = events[i]
                    z = max(0, min(t, p - s))
                    for i in range(x + c - 1, x - 1, -1):
                        if events[i][0] > t:
                            continue
                        elif events[i][0] >= t + z:
                            del events[i]
                            break
                    if z == t:
                        return '0'
                    _, n = events[i]
                    events.pop(i)
                    patience -= n
        elif query[0] == 3:
            l, r, v = query[1:]
            min_t = 1e9
            max_t = -1e9
            for t, p in events:
                if p == 0:
                    continue
                min_t = min(min_t, t - r)
                max_t = max(max_t, t - l)
            if min_t > 0 or v == 0:
                return '0'
            if max_t < v:
                return '-1'
            z = min(max_t / v - min_t, 1e9)
            if z == 0:
                return str(min_t)
            a = bisect.bisect_right(events, (max_t, -1.0))
            return str(a * z / v + min_t)

