def check_table(table):
    n = len(table)
    winning_moves = set()
    for r in range(n):
        for c in range(n):
            if (r, c) == (0, 0):  # Top-left corner
                winning_moves.add(tuple(table[r]))
            elif (r, c) == (n-1, n-1):  # Bottom-right corner
                winning_moves.add(tuple(table[n-1][c+1:] + table[:r]))
            elif (r, c) == (0, n-1):  # Just top row
                winning_moves.add(tuple(table[r][c:] for c in range(n) if c != c-1))
            elif (r, c) == (n-1, 0):  # Just right column
                winning_moves.add(tuple(table[r+1][i] for i in range(n) if i != i-1))
            else:
                winning_moves.add(tuple(table[r][c+1:] + table[:r+1] + table[r:i] + table[i+1:r+1]))
    return all(is_good_string(s) for s in winning_moves)

