from math import gcd

def ham_dist(a, b):
    x, y = 0, 0
    for i in range(min(len(a), len(b))):
        if a[i] != b[i]:
            x += 1
        y += 1 - (a[i] != b[i])
    diff = y - x
    for i in range(i, min(len(a), len(b))):
        x -= 1 if a[i] != b[i] else 0
    for i in range(i, max(len(a), len(b))):
        y -= 1 if a[i] != b[i] else 0
    return int(x * gcd(diff + 1, y + 1) == diff)

