import sys
import bisect
from collections import defaultdict

def solve():
    N, C = map(int, input().split())
    sizes = list(map(int, input().split()))

    # Create sets for each size based on the given pattern
    size_sets = defaultdict(set)
    for i, size in enumerate(sizes[::2]):
        for k in range(size):
            size_sets[size].add(i)
    for i in range(1, N + 1):
        size_sets[i].add(-(N + i))

    # Create maps for each size to store the list of potential winners
    winner_maps = defaultdict(list)
    for size in size_sets.values():
        for i in size:
            winner_maps[size].append(i)

    # Sort the sets of winners for each size
    for size in sorted(winner_maps.keys()):
        winner_maps[size].sort()

    # Function to get the minimum size needed to avoid winner over 1
    def minimum_error_size():
        if not winner_maps[size]:
            return 1
        best_size = 1
        for num_wins in winner_maps[size]:
            total_size = num_wins
            for k in range(num_wins - best_size):
                total_size += size_sets[k].pop()
            best_size = max(total_size, best_size)
        return best_size

    # Sort the sizes in ascending order
    for i in range(len(winner_maps)):
        if len(winner_maps[i]) > 1:
            winner_maps[i].sort(key=lambda x: x, reverse=True)

    res = 0
    for idx, num_wins in enumerate(winner_maps):
        res += minimum_error_size()
        num_wins = [winner for winner in num_wins if winner < 0]
        if len(num_wins) < C:
            break
        res += max(C - len(num_wins), 0)

    return res

